from __future__ import annotations
import json, html
from pathlib import Path
from collections import Counter

def write_json(path, artifacts, relationships, findings=None, case=None):
    data={'case':case or {},'artifacts':[a.to_dict() for a in artifacts],'relationships':[r.to_dict() for r in relationships],'findings':findings or []}
    Path(path).write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding='utf-8')

def write_html(path, artifacts, relationships, findings=None, case=None):
    nodes=[{'id':a.id,'label':a.name[:60],'kind':a.kind,'source':a.source,'timestamp':a.timestamp,'path':a.path,'sha256':a.sha256,'metadata':a.metadata,'observed':a.observed} for a in artifacts]
    edges=[{'from':r.source_id,'to':r.target_id,'label':r.relation,'confidence':r.confidence,'basis':r.basis,'inferred':r.inferred} for r in relationships]
    payload=json.dumps({'nodes':nodes,'edges':edges,'findings':findings or [],'case':case or {}},ensure_ascii=False).replace('</','<\\/')
    kinds=Counter(a.kind for a in artifacts); timeline=sorted([a for a in artifacts if a.timestamp],key=lambda x:x.timestamp or '')
    timeline_html=''.join(f'<tr><td>{html.escape(a.timestamp or "")}</td><td>{html.escape(a.kind)}</td><td>{html.escape(a.name[:100])}</td><td>{html.escape(a.source)}</td></tr>' for a in timeline[:5000])
    finding_html=''.join(f'<div class="finding {html.escape(f["severity"])}"><b>{html.escape(f["title"])}</b><div>{html.escape(f["detail"])}</div></div>' for f in (findings or [])) or '<div class="muted">No automated findings.</div>'
    stats=''.join(f'<div class="stat"><strong>{v}</strong><span>{html.escape(k)}</span></div>' for k,v in kinds.most_common())
    doc=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TRACE Report</title>
<style>
:root{{--bg:#0a0d10;--panel:#11161b;--panel2:#151b21;--line:#27323b;--text:#e7edf3;--muted:#8996a3;--accent:#73d5ff;--danger:#ff7b72;--warn:#e5c07b}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:13px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}header{{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px;position:sticky;top:0;background:rgba(10,13,16,.96);z-index:5}}h1{{font-size:20px;margin:0}}.muted,.sub{{color:var(--muted)}}.stats{{display:flex;gap:8px;overflow:auto}}.stat{{border:1px solid var(--line);background:var(--panel);padding:7px 11px;border-radius:8px;min-width:70px}}.stat strong{{display:block;font-size:16px}}.stat span{{font-size:10px;color:var(--muted)}}nav{{display:flex;gap:6px;padding:12px 22px;border-bottom:1px solid var(--line);position:sticky;top:76px;background:var(--bg);z-index:4}}button,.tab{{background:var(--panel);color:var(--text);border:1px solid var(--line);padding:8px 11px;border-radius:7px;cursor:pointer}}button.active,.tab.active{{border-color:var(--accent)}}section.view{{display:none}}section.view.active{{display:block}}#graphView{{height:calc(100vh - 132px);position:relative}}#graph{{position:absolute;inset:0;overflow:hidden;background:radial-gradient(circle at center,#141b22,#0a0d10 65%)}}svg{{width:100%;height:100%}}.edge{{stroke:#66727e;stroke-width:1.4;opacity:.65}}.node circle{{fill:#141b21;stroke:#73808c;stroke-width:1.5}}.node text{{fill:#dfe7ee;font-size:11px}}.node:hover circle{{stroke:var(--accent);stroke-width:2.5}}#inspector{{position:absolute;right:0;top:0;bottom:0;width:370px;background:rgba(17,22,27,.97);border-left:1px solid var(--line);padding:18px;overflow:auto}}.field{{margin:14px 0}}.label{{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}}.value{{margin-top:4px;word-break:break-word}}code{{font-family:ui-monospace,Menlo,monospace;font-size:11px}}.pill{{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:3px 7px;margin:3px 3px 0 0;color:#bdc7d0}}.relation{{border-top:1px solid var(--line);padding:11px 0}}.confidence{{font-weight:700}}.basis{{margin:6px 0 0 18px;color:#bdc7d0}}.toolbar{{position:absolute;left:14px;top:14px;z-index:2;display:flex;gap:6px}}.content{{padding:22px;max-width:1500px;margin:auto}}table{{width:100%;border-collapse:collapse;background:var(--panel)}}th,td{{padding:9px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}}th{{color:var(--muted);font-size:10px;text-transform:uppercase}}.finding{{padding:12px;border:1px solid var(--line);border-left:3px solid var(--warn);background:var(--panel);margin:8px 0;border-radius:6px}}.finding.medium{{border-left-color:var(--danger)}}.search{{width:100%;max-width:600px;background:var(--panel);border:1px solid var(--line);padding:9px;border-radius:7px;color:var(--text);margin-bottom:12px}}@media(max-width:900px){{#inspector{{width:45%}}}}@media(max-width:700px){{#inspector{{width:100%;height:45%;top:auto}}#graphView{{height:calc(100vh - 132px)}}.stats{{display:none}}}}
</style></head><body>
<header><div><h1>TRACE</h1><div class="sub">Digital Evidence Correlation Engine · {html.escape((case or {}).get('case_id',''))}</div></div><div class="stats">{stats}</div></header>
<nav><button class="tab active" onclick="show('graph',this)">Evidence Graph</button><button class="tab" onclick="show('timeline',this)">Timeline</button><button class="tab" onclick="show('findings',this)">Findings ({len(findings or [])})</button><button class="tab" onclick="show('about',this)">Methodology</button></nav>
<section id="graphView" class="view active"><div id="graph"><div class="toolbar"><button onclick="render()">Reset graph</button></div><svg id="svg"></svg><aside id="inspector"><h2>Evidence Inspector</h2><div class="muted">Select an evidence node.</div></aside></div></section>
<section id="timeline" class="view"><div class="content"><input id="search" class="search" placeholder="Filter timeline…" oninput="filterTable()"><table id="timelineTable"><thead><tr><th>Timestamp</th><th>Type</th><th>Artifact</th><th>Source</th></tr></thead><tbody>{timeline_html}</tbody></table></div></section>
<section id="findings" class="view"><div class="content"><h2>Automated findings</h2><div class="muted">Findings are indicators for investigator review, not conclusions about intent or attribution.</div>{finding_html}</div></section>
<section id="about" class="view"><div class="content"><h2>Methodology</h2><p>TRACE separates observed artifacts from inferred relationships. Relationships are generated by explicit rules and expose their supporting basis and confidence score.</p><p>Hashes identify the bytes examined at acquisition/analysis time. A hash match is evidence of byte identity, not identity of a person.</p><p>Automated indicators can be incomplete or wrong. Absence of an artifact does not prove absence of an event.</p><h3>Artifact counts</h3><pre>{html.escape(json.dumps(dict(kinds),indent=2))}</pre></div></section>
<script>const DATA={payload};const svg=document.getElementById('svg'),ins=document.getElementById('inspector');let pos={{}};
function esc(s){{return String(s??'').replace(/[&<>\"]/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}}[c]))}}
function show(id,b){{document.querySelectorAll('section.view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(id==='graph')setTimeout(render,20)}}
function layout(){{let n=DATA.nodes.length,w=svg.clientWidth||1200,h=svg.clientHeight||700;let cx=w/2-120,cy=h/2,r=Math.min(w,h)*.34;DATA.nodes.forEach((x,i)=>{{let a=2*Math.PI*i/Math.max(n,1);pos[x.id]={{x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r}}}})}}
function render(){{layout();svg.innerHTML='';let g=document.createElementNS('http://www.w3.org/2000/svg','g');svg.appendChild(g);DATA.edges.forEach(e=>{{let a=pos[e.from],b=pos[e.to];if(!a||!b)return;let l=document.createElementNS('http://www.w3.org/2000/svg','line');l.setAttribute('x1',a.x);l.setAttribute('y1',a.y);l.setAttribute('x2',b.x);l.setAttribute('y2',b.y);l.setAttribute('class','edge');g.appendChild(l)}});DATA.nodes.forEach(x=>{{let p=pos[x.id],ng=document.createElementNS('http://www.w3.org/2000/svg','g');ng.setAttribute('class','node');ng.onclick=()=>inspect(x.id);let c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',p.x);c.setAttribute('cy',p.y);c.setAttribute('r',13);ng.appendChild(c);let t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',p.x);t.setAttribute('y',p.y+30);t.setAttribute('text-anchor','middle');t.textContent=x.label;ng.appendChild(t);g.appendChild(ng)}})}}
function inspect(id){{let x=DATA.nodes.find(n=>n.id===id),es=DATA.edges.filter(e=>e.from===id||e.to===id),s='<h2>'+esc(x.label)+'</h2><div class="field"><div class="label">Observed artifact</div><div class="value"><span class="pill">'+esc(x.kind)+'</span><span class="pill">'+esc(x.source)+'</span></div></div>';for(let [k,v] of [['Timestamp',x.timestamp],['Path',x.path],['SHA-256',x.sha256]])if(v)s+='<div class="field"><div class="label">'+k+'</div><div class="value"><code>'+esc(v)+'</code></div></div>';if(x.metadata&&Object.keys(x.metadata).length)s+='<div class="field"><div class="label">Metadata</div><div class="value">'+Object.entries(x.metadata).slice(0,30).map(([k,v])=>'<div><b>'+esc(k)+'</b>: '+esc(v)+'</div>').join('')+'</div></div>';s+='<div class="field"><div class="label">Relationships</div>';es.forEach(e=>{{let other=DATA.nodes.find(n=>n.id===(e.from===id?e.to:e.from));s+='<div class="relation"><b>'+esc(e.label)+'</b> · <span class="confidence">'+Math.round(e.confidence*100)+'%</span><div>'+esc(other?.label)+'</div><ul class="basis">'+e.basis.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul><div class="muted">INFERRED · supporting evidence should be reviewed.</div></div>'}});s+='</div>';ins.innerHTML=s}}
function filterTable(){{let q=document.getElementById('search').value.toLowerCase();document.querySelectorAll('#timelineTable tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}}window.addEventListener('resize',()=>{{if(document.getElementById('graphView').classList.contains('active'))render()}});render();</script></body></html>'''
    Path(path).write_text(doc,encoding='utf-8')

def write_pdf(path, artifacts, relationships, findings=None, case=None):
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
        from reportlab.lib import colors
    except ImportError as e:
        raise RuntimeError('PDF output requires reportlab: pip install reportlab') from e
    styles=getSampleStyleSheet(); doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=36,leftMargin=36,topMargin=36,bottomMargin=36)
    story=[Paragraph('TRACE — Digital Evidence Report',styles['Title']),Paragraph(f"Case: {(case or {}).get('case_id','')}",styles['Normal']),Spacer(1,12)]
    story += [Paragraph(f"Artifacts examined: {len(artifacts)}",styles['Normal']),Paragraph(f"Inferred relationships: {len(relationships)}",styles['Normal']),Paragraph(f"Automated findings: {len(findings or [])}",styles['Normal']),Spacer(1,12)]
    story += [Paragraph('Findings',styles['Heading2'])]
    rows=[['Severity','Finding','Detail']]
    for f in (findings or []): rows.append([f['severity'],f['title'],f['detail'][:180]])
    if len(rows)==1: rows.append(['—','No automated findings',''])
    t=Table(rows,colWidths=[55,145,300]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#222831')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.grey),('VALIGN',(0,0),(-1,-1),'TOP'),('FONTSIZE',(0,0),(-1,-1),8)])); story += [t,Spacer(1,14),Paragraph('Top inferred relationships',styles['Heading2'])]
    rows=[['Relation','Confidence','Basis']]
    for r in relationships[:30]: rows.append([r.relation,f"{r.confidence:.0%}",'; '.join(r.basis)[:180]])
    if len(rows)==1: rows.append(['—','—','None'])
    t=Table(rows,colWidths=[130,65,305]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#222831')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.grey),('VALIGN',(0,0),(-1,-1),'TOP'),('FONTSIZE',(0,0),(-1,-1),8)])); story.append(t)
    story += [Spacer(1,14),Paragraph('Methodology and limitations',styles['Heading2']),Paragraph('TRACE distinguishes observed artifacts from inferred relationships. Confidence scores are prioritization scores, not probabilities. Automated findings require human review and do not establish attribution, intent or guilt.',styles['Normal'])]
    doc.build(story)
